business as (select
    CAST(publication AS Nullable(DateTime64(3,'UTC'))) AS `source_published_at`,
    CAST([source_version_key] AS Array(String)) AS `source_version_keys`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('link_v1',tuple('tenant_id','String',if(isNull(tenant_id),'1','0'),ifNull(toString(tenant_id),'')),tuple('source_system','String',if(isNull(source_system),'1','0'),ifNull(toString(source_system),'')),tuple('source_object','String',if(isNull(source_object),'1','0'),ifNull(toString(source_object),'')),tuple('source_id','String',if(isNull(source_id),'1','0'),ifNull(toString(source_id),'')),tuple('target_system','String',if(isNull(target_system),'1','0'),ifNull(toString(target_system),'')),tuple('target_object','String',if(isNull(target_object),'1','0'),ifNull(toString(target_object),'')),tuple('target_id','Nullable(String)',if(isNull(target_id),'1','0'),ifNull(toString(target_id),'')),tuple('valid_from_at','DateTime64(3,\'UTC\')',if(isNull(valid_from_at),'1','0'),ifNull(toString(toUnixTimestamp64Milli(valid_from_at)),'')))))))) AS String) AS `link_key`,
    CAST(tenant_id AS String) AS `tenant_id`,
    CAST(source_system AS String) AS `source_system`,
    CAST(source_object AS String) AS `source_object`,
    CAST(source_id AS String) AS `source_id`,
    CAST(target_system AS String) AS `target_system`,
    CAST(target_object AS String) AS `target_object`,
    CAST(target_id AS Nullable(String)) AS `target_id`,
    CAST(valid_from_at AS DateTime64(3,'UTC')) AS `valid_from_at`,
    CAST(valid_to_at AS Nullable(DateTime64(3,'UTC'))) AS `valid_to_at`,
    CAST(link_method AS String) AS `link_method`,
    CAST(if(target_id is null or target_id='','missing','verified_reference') AS String) AS `link_status`,
    CAST(is_source_deleted AS Bool) AS `is_source_deleted`,
    CAST(NULL AS Nullable(Bool)) AS `target_exists_at_reference`,
    CAST('partial' AS String) AS `calculation_status`,
    CAST(if(target_id is null or target_id='','missing_reference','target_temporal_coverage_unconfirmed') AS Nullable(String)) AS `status_reason`
from all_links),
